import type { ComponentProps, JSX } from '@solidjs/web'
import { Separator as UiSeparator } from '@ui-sdk/solid/separator'
import { omit } from 'solid-js'

import './button-group.css'

/**
 * ButtonGroup, Kitsaas's take on shadcn's ButtonGroup: joins related actions
 * (buttons, input groups, select triggers, text) into one segmented row or
 * column.
 *
 * ui-sdk has no button group, so the root is a plain `role="group"` and the
 * joining lives in `button-group.css` as attribute rules. The separator is
 * ui-sdk's headless Separator (`role="separator"`, `aria-orientation`) with
 * Kitsaas's hairline from `separator.css`.
 *
 * Purely visual: each control keeps its own tab stop. Use `Toolbar` when the
 * set should be one tab stop with arrow keys, and `ToggleGroup` for buttons
 * that stay pressed. Nest ButtonGroups to space sets apart; each nested group
 * joins its own children.
 */

export type ButtonGroupOrientation = 'horizontal' | 'vertical'

export type ButtonGroupProps = JSX.HTMLAttributes<HTMLDivElement> & {
  /** Names the group for assistive tech, e.g. "Text alignment". */
  'aria-label'?: string
  /** Defaults to `horizontal`. */
  orientation?: ButtonGroupOrientation
}

export function ButtonGroup(props: ButtonGroupProps) {
  const rest = omit(props, 'orientation')

  return (
    <div
      role="group"
      {...rest}
      data-slot="button-group"
      data-orientation={props.orientation ?? 'horizontal'}
    />
  )
}

type UiSeparatorProps = ComponentProps<typeof UiSeparator>

export type ButtonGroupSeparatorProps = Omit<
  UiSeparatorProps,
  'class' | 'render'
> & {
  /** Defaults to `vertical`, to split a horizontal group. */
  orientation?: UiSeparatorProps['orientation']
  class?: UiSeparatorProps['class']
  render?: UiSeparatorProps['render']
}

/**
 * The seam between filled buttons (`neutral`, `contrast`…); `outline` buttons
 * draw their own. Pass `orientation="horizontal"` inside a vertical group.
 */
export function ButtonGroupSeparator(props: ButtonGroupSeparatorProps) {
  const rest = omit(props, 'orientation', 'class', 'render')

  return (
    <UiSeparator
      {...rest}
      class={props.class}
      render={props.render}
      orientation={props.orientation ?? 'vertical'}
    />
  )
}

export type ButtonGroupTextProps = JSX.HTMLAttributes<HTMLDivElement>

/** A static label or value joined into a ButtonGroup, e.g. a URL prefix. */
export function ButtonGroupText(props: ButtonGroupTextProps) {
  return <div {...props} data-slot="button-group-text" />
}

/*
 * ButtonGroup, after shadcn's `button-group` (MIT), drawn with Kitsaas tokens.
 * ui-sdk has no button group: the root is a plain `role="group"` and the
 * separator is ui-sdk's Separator, styled by `separator.css`.
 *
 * Direct children lose the corners they share with a neighbour; nested groups
 * only add a gap, since each joins its own children. Kitsaas draws outlines
 * with an inset box-shadow, not a border, so instead of shadcn's `border-l-0`
 * adjacent outlined controls overlap by 1px to leave a single hairline. A
 * hovered or focused child rises above its neighbours so its focus ring is
 * never clipped.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@import "./separator.css";

/*
 * Joins look at segments, not :first-child / :last-child: ui-sdk renders a
 * Select's or Menu's popover and hidden form input as siblings of the trigger,
 * and those must not decide which corners stay round.
 */
@layer components {
  [data-slot="button-group"] {
    display: flex;
    width: fit-content;
    align-items: stretch;
    isolation: isolate;
  }

  [data-slot="button-group"][data-orientation="vertical"] {
    flex-direction: column;
  }

  [data-slot="button-group"]:has(> [data-slot="button-group"]) {
    gap: 8px;
  }

  [data-slot="button-group"] > :is(:hover, :focus-visible, :focus-within) {
    position: relative;
    z-index: 1;
  }

  [data-slot="button-group"] > :is([data-slot="input-group"], [data-slot="select-trigger"]) {
    width: auto;
    flex: 1 1 auto;
  }

  [data-slot="button-group"][data-orientation="horizontal"]
    > :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    )
    ~ :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    ) {
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  [data-slot="button-group"][data-orientation="horizontal"]
    > :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    ):has(
      ~ :is(
        [data-slot="button"],
        [data-slot="select-trigger"],
        [data-slot="input-group"],
        [data-slot="button-group-text"]
      )
    ) {
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  [data-slot="button-group"][data-orientation="vertical"]
    > :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    )
    ~ :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    ) {
    border-start-start-radius: 0;
    border-start-end-radius: 0;
  }

  [data-slot="button-group"][data-orientation="vertical"]
    > :is(
      [data-slot="button"],
      [data-slot="select-trigger"],
      [data-slot="input-group"],
      [data-slot="button-group-text"]
    ):has(
      ~ :is(
        [data-slot="button"],
        [data-slot="select-trigger"],
        [data-slot="input-group"],
        [data-slot="button-group-text"]
      )
    ) {
    border-end-start-radius: 0;
    border-end-end-radius: 0;
  }

  /* Outlined neighbours share one hairline. */
  [data-slot="button-group"][data-orientation="horizontal"]
    > :is([data-variant="outline"], [data-slot="button-group-text"])
    + :is([data-variant="outline"], [data-slot="button-group-text"], [data-slot="input-group"]) {
    margin-inline-start: -1px;
  }

  [data-slot="button-group"][data-orientation="vertical"]
    > :is([data-variant="outline"], [data-slot="button-group-text"])
    + :is([data-variant="outline"], [data-slot="button-group-text"], [data-slot="input-group"]) {
    margin-block-start: -1px;
  }

  /* The separator sits on top of the filled buttons' shadows. */
  [data-slot="button-group"] > [data-slot="separator"] {
    position: relative;
    z-index: 2;
  }

  [data-slot="button-group-text"] {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0 11px;
    border-radius: 6px;
    background-color: var(--v2-background-bg-layer-02);
    box-shadow: inset 0 0 0 1px var(--v2-border-border-muted);
    color: var(--v2-text-text-muted);
    font-weight: 440;
    font-size: 13px;
    line-height: 20px;
    white-space: nowrap;
    user-select: none;
  }

  [data-slot="button-group-text"] svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: var(--v2-icon-icon-muted);
  }
}
